ACT=[("Eiffel Tower","Sightseeing",2500,120),("Louvre Museum","Culture",1800,180),("Seine River Cruise","Sightseeing",2200,90),("Le Marais Food Walk","Food",3000,150),("British Museum","Culture",0,150),("Tower Bridge","Sightseeing",1800,90),("Canal Cruise","Sightseeing",2200,90),("Rijksmuseum","Culture",2500,150),("Brandenburg Gate","Sightseeing",0,60),("Berlin Food Tour","Food",2800,150),("Colosseum","Culture",2500,150),("Trastevere Dinner","Food",2200,120),("Sagrada Familia","Culture",3000,120),("Park Guell","Nature",1200,120),("Burj Khalifa","Sightseeing",4500,120),("Dubai Desert Safari","Adventure",6000,360),("Shibuya Food Tour","Food",3500,180),("Meiji Shrine","Culture",0,90),("Marina Bay Sands","Sightseeing",2500,120),("Gardens by the Bay","Nature",1800,150),("Grand Palace","Culture",1200,150),("Street Food Tour","Food",1800,180),("Gateway of India","Sightseeing",0,60),("Elephanta Caves","Culture",1600,300),("Sabarmati Ashram","Culture",0,90),("Adalaj Stepwell","Culture",500,120)]
async def main():
 async with SessionLocal() as db:
  existing=(await db.scalar(select(City).limit(1)))
  if existing: print("Seed already present"); return
  for i,(n,c,r,lat,lon) in enumerate(CITIES):
   city=City(name=n,country=c,region=r,latitude=lat,longitude=lon,cost_index=round(1+(i%5)*.35,2),popularity=95-(i%20),description=f"Explore {n}, {c}.",image_url=f"https://images.unsplash.com/featured/?{n.replace(' ','%20')},travel"); db.add(city); await db.flush()
   for j,(an,cat,cost,dur) in enumerate(ACT):
    if j%len(CITIES)%4==i%4: db.add(Activity(city_id=city.id,name=an,description=f"A popular {cat.lower()} experience in {n}.",category=cat,estimated_cost=cost,duration_minutes=dur,currency="INR",rating=4.2+(j%8)/10,image_url=f"https://images.unsplash.com/featured/?{an.replace(' ','%20')}"))
  await db.commit(); print("Seeded cities and activities")
if __name__=="__main__":asyncio.run(main())
